CREATE TYPE "MarketStatus" AS ENUM ('DRAFT','ACTIVE','RETIRED');
CREATE TYPE "GlobalMeasurementSystem" AS ENUM ('METRIC','IMPERIAL');
CREATE TABLE "Market" ("id" TEXT PRIMARY KEY,"key" TEXT NOT NULL UNIQUE,"countryCode" CHAR(2) NOT NULL,"regionCode" TEXT,"status" "MarketStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "MarketConfiguration" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"version" INTEGER NOT NULL,"status" "MarketStatus" NOT NULL DEFAULT 'DRAFT',"defaultLocale" TEXT NOT NULL,"supportedLocales" TEXT[] NOT NULL,"defaultCurrency" CHAR(3) NOT NULL,"supportedCurrencies" TEXT[] NOT NULL,"defaultTimezone" TEXT NOT NULL,"supportedTimezones" TEXT[] NOT NULL,"measurementSystem" "GlobalMeasurementSystem" NOT NULL,"dateFormatPolicy" JSONB NOT NULL,"timeFormatPolicy" JSONB NOT NULL,"numberFormatPolicy" JSONB NOT NULL,"currencyDisplayPolicy" JSONB NOT NULL,"phonePolicy" JSONB NOT NULL,"addressPolicy" JSONB NOT NULL,"taxPolicyRef" TEXT,"paymentPolicyRef" TEXT,"bookingPolicyRef" TEXT,"bookingPolicy" JSONB NOT NULL,"featureFlags" JSONB NOT NULL,"supportedPaymentMethods" TEXT[] NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("marketId","version"));
CREATE TABLE "TenantGlobalizationProfile" ("id" TEXT PRIMARY KEY,"businessId" TEXT NOT NULL UNIQUE REFERENCES "Business"("id") ON DELETE CASCADE,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"marketConfigurationId" TEXT NOT NULL REFERENCES "MarketConfiguration"("id") ON DELETE RESTRICT,"preferredLocale" TEXT NOT NULL,"preferredCurrency" CHAR(3) NOT NULL,"preferredTimezone" TEXT NOT NULL,"measurementSystem" "GlobalMeasurementSystem" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "MarketTranslation" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE CASCADE,"locale" TEXT NOT NULL,"namespace" TEXT NOT NULL,"translationKey" TEXT NOT NULL,"value" TEXT NOT NULL,"version" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("marketId","locale","namespace","translationKey","version"));
CREATE TABLE "CurrencyDefinition" ("code" CHAR(3) PRIMARY KEY,"minorUnit" INTEGER NOT NULL,"displayName" TEXT NOT NULL,"symbol" TEXT,"roundingIncrementMinor" INTEGER NOT NULL DEFAULT 1,"isActive" BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE "FxRateSnapshot" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE RESTRICT,"baseCurrency" CHAR(3) NOT NULL,"quoteCurrency" CHAR(3) NOT NULL,"rate" DECIMAL(24,12) NOT NULL,"provider" TEXT NOT NULL,"version" INTEGER NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("marketId","baseCurrency","quoteCurrency","provider","version"));
CREATE TABLE "MarketCategoryAvailability" ("id" TEXT PRIMARY KEY,"marketId" TEXT NOT NULL REFERENCES "Market"("id") ON DELETE CASCADE,"categoryId" TEXT NOT NULL REFERENCES "PlatformCategory"("id") ON DELETE CASCADE,"serviceTypeId" TEXT,"enabled" BOOLEAN NOT NULL DEFAULT true,"localizedMetadata" JSONB,UNIQUE("marketId","categoryId","serviceTypeId"));
ALTER TABLE "User" ADD COLUMN "preferredLanguage" TEXT, ADD COLUMN "preferredLocale" TEXT, ADD COLUMN "preferredCurrency" CHAR(3), ADD COLUMN "preferredTimezone" TEXT;
ALTER TABLE "Customer" ADD COLUMN "preferredLanguage" TEXT, ADD COLUMN "preferredLocale" TEXT, ADD COLUMN "preferredCurrency" CHAR(3), ADD COLUMN "preferredTimezone" TEXT, ADD COLUMN "measurementSystem" "GlobalMeasurementSystem";
ALTER TABLE "Appointment" ADD COLUMN "marketConfigurationId" TEXT REFERENCES "MarketConfiguration"("id") ON DELETE RESTRICT, ADD COLUMN "bookingTimezone" TEXT, ADD COLUMN "customerTimezone" TEXT;
CREATE INDEX "Market_countryCode_status_idx" ON "Market"("countryCode","status");
CREATE INDEX "MarketConfiguration_marketId_status_effectiveFrom_effectiveTo_idx" ON "MarketConfiguration"("marketId","status","effectiveFrom","effectiveTo");
CREATE INDEX "TenantGlobalizationProfile_marketId_preferredLocale_preferredCurrency_idx" ON "TenantGlobalizationProfile"("marketId","preferredLocale","preferredCurrency");
CREATE INDEX "MarketTranslation_marketId_locale_namespace_idx" ON "MarketTranslation"("marketId","locale","namespace");
CREATE INDEX "FxRateSnapshot_marketId_baseCurrency_quoteCurrency_effectiveAt_expiresAt_idx" ON "FxRateSnapshot"("marketId","baseCurrency","quoteCurrency","effectiveAt","expiresAt");
CREATE INDEX "MarketCategoryAvailability_marketId_enabled_categoryId_idx" ON "MarketCategoryAvailability"("marketId","enabled","categoryId");
CREATE INDEX "Appointment_marketConfigurationId_idx" ON "Appointment"("marketConfigurationId");
